def opposes?(idxBattler1, idxBattler2 = 0)
  idxBattler1 = idxBattler1.index if idxBattler1.respond_to?("index")
  idxBattler2 = idxBattler2.index if idxBattler2.respond_to?("index")
  return (idxBattler1 & 1) != (idxBattler2 & 1)
end

def opposes?(i = 0)
  i = i.index if i.respond_to?("index")
  return (@index & 1) != (i & 1)
end

def pbInitBlank
  @name           = ""
  @species        = 0
  @form           = 0
  @level          = 0
  @hp = @totalhp  = 0
  @types          = []
  @ability_id     = nil
  @item_id        = nil
  @attack = @defense = @spatk = @spdef = @speed = 0
  @status         = :NONE
  @statusCount    = 0
  @pokemon        = nil
  @pokemonIndex   = -1
  @participants   = []
  @moves          = []
end

def pbInitialize(pkmn, idxParty, batonPass = false)
  pbInitPokemon(pkmn, idxParty)
  pbInitEffects(batonPass)
  @damageState.reset
end

def pbInitPokemon(pkmn, idxParty)
  raise _INTL("An egg can't be an active Pokémon.") if pkmn.egg?
  @name         = pkmn.name
  @species      = pkmn.species
  @form         = pkmn.form
  @level        = pkmn.level
  @hp           = pkmn.hp
  @totalhp      = pkmn.totalhp
  @types        = pkmn.types
  @ability_id   = pkmn.ability_id
  @item_id      = pkmn.item_id
  @attack       = pkmn.attack
  @defense      = pkmn.defense
  @spatk        = pkmn.spatk
  @spdef        = pkmn.spdef
  @speed        = pkmn.speed
  @status       = pkmn.status
  @statusCount  = pkmn.statusCount
  @pokemon      = pkmn
  @pokemonIndex = idxParty
  @participants = []   # Participants earn Exp. if this battler is defeated
  @moves        = []
  pkmn.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, m)
  end
end
